/// ==============================================================
class CommissionRogatoireIntroPage extends StatefulWidget {
  const CommissionRogatoireIntroPage({super.key});

  /// Route (si tu veux l’ouvrir par nom)
  static const String routeName =

;

  @override
  State<CommissionRogatoireIntroPage> createState() =>
      _CommissionRogatoireIntroPageState();
