  // Animations
  late final AnimationController _fadeCtrl = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1100),
  )..forward();

  late final AnimationController _subtitleCtrl = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 900),
  );

  late final AnimationController _buttonPulseCtrl = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1300),
    lowerBound: 0.0,
    upperBound: 1.0,
  )..repeat(reverse: true);

  // Écriture IA (typewriter)
  static const String _titleFull =

;
  int _typedCount = 0;
  Timer? _typeTimer;

  @override
  void initState() {
    super.initState();
    _typeTimer = Timer.periodic(const Duration(milliseconds: 36), (t) {
      if (!mounted) return;
      if (_typedCount < _titleFull.length) {
        setState(() => _typedCount++);
      } else {
        t.cancel();
        _subtitleCtrl.forward();
      }
    });
  }

  @override
  void dispose() {
    _typeTimer?.cancel();
    _fadeCtrl.dispose();
    _subtitleCtrl.dispose();
    _buttonPulseCtrl.dispose();
    super.dispose();
  }

  Future<void> _onStart() async {
    if (!mounted) return;
    await Navigator.of(context).push(
      PageRouteBuilder(
        transitionDuration: const Duration(milliseconds: 420),
        pageBuilder: (context, animation, secondaryAnimation) {
          return const _RouteShimToTarget();
        },
        transitionsBuilder: (context, animation, secondary, child) {
          return FadeTransition(
            opacity: CurvedAnimation(
              parent: animation,
              curve: Curves.easeOutCubic,
            ),
            child: child,
          );
        },
      ),
    );
  }

